command:
// ==========================================
// LUNAS WIRKUNG: GEISTERRUF (ZERZAL)
//
// - Rufweite QS × 20 Schritt
// - bekannte Geister erst beim GM-Aufruf suchen
// - GM wählt mögliche bekannte Geister
// - bei mehreren bekannten Geistern entscheidet der Zufall
// - zusätzliche unbekannte Geister frei bestimmbar
// - gespeicherter Wirkender, kein erneutes Target
// - eine gemeinsame Karte über Block 19.8
// - roter GM-Button „Effekt anwenden“
// - dieselbe Karte wird nach Verarbeitung aktualisiert
// - keine zusätzliche Ergebniskarte
// ==========================================

(async function () {
    const macroUuid = this?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.CheckTarget ||
        !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.Geometrie?.Distanz ||
        !globalThis.DSK?.GMAnfrage?.Speichern ||
        !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen ||
        !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) {
            return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        }

        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.CheckTarget ||
        !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.Token?.Finde ||
        !DSK_FW?.Geometrie?.Distanz ||
        !DSK_FW?.GMAnfrage?.Speichern ||
        !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen ||
        !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");
    }

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Geisterruf";
    const vollerName = "Geisterruf (Zerzal)";
    const ahne = "Zerzal";
    const flagKey = "pendingGeisterrufZerzal";

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenQS");
        }

        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenMessageId");
        }
    };

    // +++ 3 - GM-DIALOG +++++++++++++++++++++++++++++++++++++++

    const frageGeisterAuswahl = async ({
        casterName,
        qs,
        radius,
        geister
    }) => {
        const geisterListe = geister.length
            ? geister.map(({ token, distanz }) => `
                <label style="display:flex;align-items:center;gap:7px;margin-bottom:6px;padding:6px 8px;background:rgba(255,255,255,.35);border-radius:3px;cursor:pointer;">
                    <input type="checkbox" name="geist" value="${token.id}">
                    <span style="flex:1;">
                        <b>${token.name}</b><br>
                        <span style="font-size:.82em;color:#555;">
                            Entfernung: ${Math.round(distanz * 10) / 10} Schritt
                        </span>
                    </span>
                </label>
            `).join("")
            : `<p style="margin:0;color:#555;font-style:italic;">
                Keine bekannten Geister innerhalb der Rufweite.
            </p>`;

        return foundry.applications.api.DialogV2.wait({
            window: { title: vollerName },
            position: { width: 460 },

            content: `<form>
                <div style="font-family:'Signika',sans-serif;">
                    ${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}

                    <div class="dskbox2" style="margin-top:10px;">
                        <p style="margin:0 0 8px;">
                            <b>${casterName}</b> ruft in die Zwischenwelt.
                        </p>

                        ${DSK_FW.UI.List([
                            `<b>QS:</b> ${qs}`,
                            `<b>Rufweite:</b> ${radius} Schritt`
                        ])}

                        <hr>

                        <p style="margin:0 0 7px;font-weight:bold;">
                            Welche bekannten Geister können auf den Ruf aufmerksam werden?
                        </p>

                        <div style="padding:8px;background:rgba(0,0,0,.05);border-radius:4px;max-height:190px;overflow-y:auto;">
                            ${geisterListe}
                        </div>

                        <hr>

                        <div style="padding:8px 10px;background:rgba(118,48,27,.06);border:1px solid rgba(118,48,27,.2);border-radius:4px;">
                            <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;">
                                <label for="unbekannteGeister" style="font-weight:bold;">
                                    Unbekannte Geister:
                                </label>

                                <input id="unbekannteGeister" type="number"
                                    name="unbekannteGeister"
                                    value="${geister.length ? 0 : 1}"
                                    min="0" max="20" step="1"
                                    style="width:70px;text-align:center;">
                            </div>

                            <p style="margin:6px 0 0;font-size:.84em;color:#555;">
                                Anzahl bislang unbekannter oder noch nicht platzierter Geister.
                            </p>
                        </div>

                        <hr>

                        <p style="font-size:.85em;color:#444;margin:0;">
                            <i>
                                Werden mehrere bekannte Geister ausgewählt, entscheidet der
                                Zufall, welcher Geist tatsächlich antwortet.
                            </i>
                        </p>
                    </div>
                </div>
            </form>`,

            buttons: [
                {
                    action: "ok",
                    label: "Ruf auslösen",
                    icon: "fas fa-bullhorn",
                    default: true,

                    callback: event => {
                        const form = event.target.closest("form");
                        const formData = new FormData(form);

                        return {
                            selectedIds: Array.from(
                                form.querySelectorAll('input[name="geist"]:checked')
                            ).map(element => element.value),

                            unbekannteGeister: Math.max(
                                0,
                                Math.min(
                                    20,
                                    Math.trunc(
                                        Number(formData.get("unbekannteGeister")) || 0
                                    )
                                )
                            )
                        };
                    }
                },
                {
                    action: "cancel",
                    label: "Abbrechen",
                    icon: "fas fa-times",
                    callback: () => null
                }
            ],

            rejectClose: false
        });
    };

    // +++ 4 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++

    const verarbeiteGeisterruf = async (casterActor, daten) => {
        if (!casterActor || !daten || !game.user.isGM) return false;

        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
            ui.notifications.warn(
                "Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum wirkenden Akteur."
            );
            return false;
        }

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(
                `Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`
            );
            return false;
        }

        const casterToken = DSK_FW.Token.Finde(
            casterActor,
            daten.casterTokenId,
            daten.casterTokenUuid
        );

        if (!casterToken) {
            ui.notifications.warn(
                `Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`
            );
            return false;
        }

        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const radius = qs * 20;
        const casterName =
            daten.casterName || DSK_FW.ResolveTokenName(casterActor);

        const geister = (canvas.tokens?.placeables || [])
            .filter(token =>
                token?.actor &&
                token.id !== casterToken.id &&
                DSK_FW.Effekt.CheckTarget(token.actor, "geist")
            )
            .map(token => ({
                token,
                distanz: DSK_FW.Geometrie.Distanz(casterToken, token)
            }))
            .filter(eintrag => eintrag.distanz <= radius)
            .sort((a, b) =>
                String(a.token.name).localeCompare(String(b.token.name), "de")
            );

        const dialogResult = await frageGeisterAuswahl({
            casterName,
            qs,
            radius,
            geister
        });

        // Abbruch: Anfrage bleibt bestehen.
        if (dialogResult === null) {
            ui.notifications.info(
                "Luna sagt 🌙: Die Geisterauswahl wurde abgebrochen. Die Anfrage bleibt erhalten."
            );
            return false;
        }

        const ausgewaehlteGeister = dialogResult.selectedIds
            .map(id => geister.find(eintrag => eintrag.token.id === id)?.token)
            .filter(token =>
                token?.actor &&
                DSK_FW.Effekt.CheckTarget(token.actor, "geist") &&
                DSK_FW.Geometrie.Distanz(casterToken, token) <= radius
            );

        const bekannterGeist = ausgewaehlteGeister.length
            ? ausgewaehlteGeister[
                Math.floor(Math.random() * ausgewaehlteGeister.length)
            ]
            : null;

        const unbekannteGeister = dialogResult.unbekannteGeister;
        const erfolgreich = Boolean(bekannterGeist || unbekannteGeister > 0);
        const antworten = [];

        if (bekannterGeist) {
            antworten.push({
                name: bekannterGeist.name,
                rolle: "Antwortender Geist"
            });
        }

        if (unbekannteGeister > 0) {
            antworten.push({
                name: `Unbekannt (${unbekannteGeister})`,
                rolle: unbekannteGeister === 1
                    ? "Unbekannter Geist"
                    : "Unbekannte Geister"
            });
        }

        const beschreibung =
            `<b>${casterName}</b> ruft Geister aus der Zwischenwelt.` +
            `<br><br><b>Reichweite:</b> ${radius} Schritt` +
            `<br><b>Qualitätsstufe:</b> ${qs}` +
            (
                unbekannteGeister === 1
                    ? `<br><br>Ein bislang unbekannter oder noch nicht platzierter Geist reagiert auf den Ruf und nähert sich der Quelle.`
                    : unbekannteGeister > 1
                        ? `<br><br><b>${unbekannteGeister}</b> bislang unbekannte oder noch nicht platzierte Geister reagieren auf den Ruf und nähern sich der Quelle.`
                        : ""
            );

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId,
            gabenName: vollerName,
            ahne,
            beschreibung,
            wirkender: casterName,
            ziele: antworten,
            misserfolge: erfolgreich
                ? []
                : [{
                    name: "Kein Geist",
                    grund: "Kein Geist antwortet auf den Ruf"
                }],
            dauerText: "sofort",
            erfolgreich
        });

        if (erfolgreich) {
            ui.notifications.info(
                `Luna sagt 🌙: ${antworten.length} Antwort(en) auf den Geisterruf wurden bestimmt.`
            );
        } else {
            ui.notifications.warn(
                "Luna sagt 🌙: Kein Geist antwortet auf den Ruf."
            );
        }

        // Auch „keine Antwort“ ist eine vollständig verarbeitete Anfrage.
        return true;
    };

    // +++ 5 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten =
                    DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);

                if (!daten) continue;

                if (await verarbeiteGeisterruf(anfrageActor, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(
                        anfrageActor,
                        flagKey
                    );
                }
            }

            return;
        }
    }

    // +++ 6 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    let casterActor =
        canvas.tokens.controlled[0]?.actor ||
        game.user.character ||
        null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables
                .map(token => token.actor)
                .find(actor =>
                    actor?.getFlag("world", "letzteGabenQS") !== undefined
                ) ||
            game.actors.find(actor =>
                actor.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            null;
    }

    if (!casterActor) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle zuerst den Token des Wirkenden aus!"
        );
    }

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);

    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Konnte den Token des Wirkenden nicht finden!"
        );
    }

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,
        suchbegriffe: ["Geisterruf Probe", "Geisterruf"],
        testDataObj:
            typeof testData !== "undefined" ? testData : null,
        fallback: 0,
        protokollieren: true
    });

    if (qs <= 0) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung: "Der Ruf verhallt ungehört in der Zwischenwelt.",
            wirkender: casterName,
            ziele: [],
            misserfolge: [{
                name: casterName,
                grund: "Probe fehlgeschlagen"
            }],
            dauerText: "sofort",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 7 - GEMEINSAME KARTE + ROTER GM-BUTTON +++++++++++++

    const radius = qs * 20;

    const beschreibung =
        `<b>${casterName}</b> ruft Geister aus der Zwischenwelt.` +
        `<br><br><b>Reichweite:</b> ${radius} Schritt` +
        `<br><b>Qualitätsstufe:</b> ${qs}` +
        `<br><br>Die Spielleitung entscheidet, welche bekannten Geister den Ruf hören und wie viele unbekannte Geister zusätzlich reagieren.`;

    const gmLink = DSK_FW.GabenUI.GMMakroButton(
        macroUuid,
        "Effekt anwenden",
        "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

    const nachricht =
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung,
            wirkender: casterName,
            ziele: [],
            misserfolge: [],
            dauerText: "sofort",
            gmLink,
            gmBereich: !game.user.isGM,
            anfragenderUserId: game.user.id
        });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error(
            "Luna sagt 🌙: Die Geisterruf-Karte konnte nicht erstellt werden!"
        );
    }

    // +++ 8 - ANFRAGEDATEN ++++++++++++++++++++++++++++++++++++

    const anfrageDaten = {
        casterUuid: casterActor.uuid,
        casterName,
        casterTokenId: casterToken.id,
        casterTokenUuid:
            casterToken.document?.uuid ||
            casterToken.uuid ||
            null,
        qs,
        sceneId: canvas.scene?.id || null,
        requestedByUserId: game.user.id,
        messageId: nachricht.id,
        macroUuid,
        erstellt: Date.now()
    };

    // +++ 9 - GM DIREKT ODER ANFRAGE SPEICHERN +++++++++++++++

    if (game.user.isGM) {
        await verarbeiteGeisterruf(
            casterActor,
            anfrageDaten
        );

        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(
        casterActor,
        flagKey,
        anfrageDaten
    );

    // +++ 10 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);

    ui.notifications.info(
        "Luna sagt 🌙: Der Geisterruf wurde bei der Spielleitung beantragt."
    );

}).call(this);
